import { PROGRESS_BAR_STAGES, PROGRESS_COUNT, OPERATIONS, PROGRESS_INTERVAL, CURRENT_PROGRESS_INDEX } from "../constants";
import { ProgressEventIdMap, ProgressEvent, VideoMediaInfo, ContentLengthProgressTracker, ProgressStage, ContentLengthUnit } from "../interfaces";
class ProgressManager {
    private progressEventIdMap: ProgressEventIdMap | {} = {};
    private onProgressEvent: (id: string, progressPercentage: number) => void;
    private contentLengthTrackers: Map<string, ContentLengthProgressTracker> = new Map();
    
    /**
     * Initializes the progress manager for a specific task or process.
     *
     * @param onProgressEvent - A callback function that is triggered to report progress updates.
     *                          It receives the progress percentage and an identifier as arguments.
     * @param id - A unique identifier for the task or process being tracked.
     */
    start(id: string, onProgressEvent: (id: string, progressPercentage: number) => void) {
      if (this.progressEventIdMap[id] && Object.keys(this.progressEventIdMap[id]).length !== 0) {
        this.stop(id);
      }
      this.onProgressEvent = onProgressEvent;
      this.progressEventIdMap[id] = {
        currentProgressStateIndex: 0,
      };
      this.startStage(id);
    }

    /**
     * Retrieves the progress information for the specified current stage of the progress bar.
     *
     * @param currentStage - The index of the current stage in the progress bar.
     * @returns The progress information object corresponding to the current stage.
     */
    private getProgressInformationForCurrentStage(currentStage: number) {
      const stages = Object.keys(PROGRESS_BAR_STAGES[OPERATIONS]);
      const progressInformationForCurrentStage = PROGRESS_BAR_STAGES[OPERATIONS][stages[currentStage]];
      return progressInformationForCurrentStage;
    }

    /**
     * Retrieves the maximum percentage value associated with the current stage of progress.
     *
     * @param currentStage - The current stage of the progress workflow.
     * @returns The maximum percentage value for the specified stage.
     */
    private getMaxPercentageForCurrentStage(currentStage: number) {
      const progressInformationForCurrentStage = this.getProgressInformationForCurrentStage(currentStage);
      return progressInformationForCurrentStage.maxPercentage;
    }

    /**
     * Starts a progress stage for a given identifier. This method initializes and periodically updates
     * the progress count for the specified stage, invoking a callback function if provided. If no more
     * stages exist, the progress is stopped and the associated resources are cleaned up.
     *
     * @param id - The unique identifier for the progress stage.
     *
     * Functionality:
     * - Retrieves the progress information for the current stage using the provided identifier.
     * - Logs a message and cleans up resources if no more stages exist.
     * - Periodically increments the progress count and invokes the `onProgressEvent` callback with the updated count.
     * - Stops the progress update when the maximum percentage for the current stage is reached.
     *
     * Dependencies:
     * - `PROGRESS_BAR_STAGES.stepSizeInPercentage` - The step size for incrementing the progress count.
     * - `PROGRESS_BAR_STAGES.stepDurationInMilliSecs` - The interval duration for periodic updates.
     * - `this.getProgressInformationForCurrentStage` - Retrieves progress information for the current stage.
     * - `this.onProgressEvent` - Optional callback function to handle progress updates.
     *
     * Cleanup:
     * - Clears the interval and removes the progress event mapping when the progress is complete or no stages exist.
     */
    private startStage(id: string) {
        let count = this.progressEventIdMap[id][PROGRESS_COUNT] || 0;
        // periodic update
        this.progressEventIdMap[id][PROGRESS_INTERVAL] = setInterval(() => {
          count += PROGRESS_BAR_STAGES.stepSizeInPercentage;
          this.progressEventIdMap[id][PROGRESS_COUNT] = count;
          this.onProgressEvent && this.onProgressEvent(id, count);
          if (count >= this.getMaxPercentageForCurrentStage(this.progressEventIdMap[id][CURRENT_PROGRESS_INDEX])) {
            clearInterval(this.progressEventIdMap[id][PROGRESS_INTERVAL]);
            this.progressEventIdMap[id][PROGRESS_INTERVAL] = null;
          }
        }, PROGRESS_BAR_STAGES.stepDurationInMilliSecs);
        this.progressEventIdMap[id][PROGRESS_COUNT] = count;
    }

    /**
     * Determines if the next stage of progress should be started for a given ID.
     * If the current progress state index is less than the total number of stages,
     * it initiates the next stage. Otherwise, it stops the progress for the given ID.
     *
     * @param id - The unique identifier for the progress instance.
     */
    private startNextStage(id: string) {
      const stages = Object.keys(PROGRESS_BAR_STAGES[OPERATIONS]);
      if (this.progressEventIdMap[id][CURRENT_PROGRESS_INDEX] < stages.length) {
        this.startStage(id);
        return;
      }
      this.stop(id);
    }

    /**
     * Marks the current stage of progress as completed for a given ID.
     * 
     * This method updates the progress information for the specified ID, 
     * setting the progress count to the maximum percentage of the current stage, 
     * triggering the progress event callback (if defined), clearing the interval 
     * associated with the progress, and advancing to the next progress state index.
     * 
     * @param id - The unique identifier for the progress event to update.
     */
    public stageCompleted(id: string) {
      const progressInfo: ProgressEvent = this.progressEventIdMap[id];
      if (!progressInfo || Object.keys(progressInfo).length === 0) {
        return;
      }
      const progressInformationForCurrentStage = this.getProgressInformationForCurrentStage(progressInfo.currentProgressStateIndex);
      this.progressEventIdMap[id][PROGRESS_COUNT] = progressInformationForCurrentStage.maxPercentage;
      this.progressEventIdMap[id][CURRENT_PROGRESS_INDEX]+=1;
      this.onProgressEvent && this.onProgressEvent(id, this.progressEventIdMap[id][PROGRESS_COUNT]);
      if (!this.progressEventIdMap[id][PROGRESS_INTERVAL]) {
        this.startNextStage(id);
        return;
      }
      if (this.progressEventIdMap[id][CURRENT_PROGRESS_INDEX] >= Object.keys(PROGRESS_BAR_STAGES[OPERATIONS]).length) {
        this.stop(id);
      }
    }

    /**
     * Handles the failure of a specific stage by clearing the associated progress interval
     * and removing the progress event from the internal map.
     *
     * @param id - The unique identifier of the progress event to be marked as failed.
     */
    public stop(id: string) {
      const progressInfo: ProgressEvent = this.progressEventIdMap[id];
      if (!progressInfo || Object.keys(progressInfo).length === 0) {
        return;
      }
      clearInterval(progressInfo.progressInterval);
      delete this.progressEventIdMap[id];
      this.contentLengthTrackers.delete(id);
    }

    /**
     * Initializes content-length-based progress tracking for a download.
     * @param videoMediaInfo - The video media information containing content length data
     * @param id - Unique identifier for this download
     * @param onProgressEvent - Callback function to report progress updates
     */
    public startDownloadProgressStatus(
        videoMediaInfo: VideoMediaInfo, 
        id: string, 
        onProgressEvent: (id: string, progressPercentage: number) => void
    ): void {
        const audioContentLengthBytes = this.convertToBytes(
            videoMediaInfo.audioSpecificInfo.contentLengthInKbOrMbOrGb,
            videoMediaInfo.audioSpecificInfo.contentLengthUnit
        );
        const videoContentLengthBytes = videoMediaInfo.videoSpecificInfo ? 
            this.convertToBytes(
                videoMediaInfo.videoSpecificInfo.contentLengthInKbOrMbOrGb,
                videoMediaInfo.videoSpecificInfo.contentLengthUnit
            ) : 0;
        const totalContentLengthBytes = audioContentLengthBytes + videoContentLengthBytes;
        if (totalContentLengthBytes === 0) {
            console.warn(`ProgressManager: No content length available for ${id}`);
            return;
        }
        this.onProgressEvent = onProgressEvent;
        const tracker: ContentLengthProgressTracker = {
            videoId: videoMediaInfo.videoId,
            totalContentLengthBytes: totalContentLengthBytes,
            audioContentLengthBytes,
            videoContentLengthBytes,
            currentDownloadedBytes:  Math.floor(totalContentLengthBytes * 0.0001), // Start at 0.01%
            currentStage: ProgressStage.FETCH_OPERATION
        };
        
        
        this.contentLengthTrackers.set(id, tracker);        
        // Report initial progress
        this.reportContentLengthProgress(id);
    }

    /**
     * Updates progress for a specific download based on content length.
     * @param id - Unique identifier for the download
     * @param additionalBytes - Additional bytes downloaded
     * @param stage - Current stage of the download process
     */
    public updateContentLengthProgress(
        id: string, 
        additionalBytes: number, 
        stage: ProgressStage
    ): void {
        const tracker = this.contentLengthTrackers.get(id);
        if (!tracker) {
            console.warn(`ProgressManager: No content-length tracker found for id: ${id}`);
            return;
        }

        tracker.currentDownloadedBytes += additionalBytes;
        tracker.currentStage = stage;
        
        this.reportContentLengthProgress(id);
    }

    /**
     * Sets the current stage for a content-length-based download.
     * @param id - Unique identifier for the download
     * @param stage - New stage
     */
    public setContentLengthStage(id: string, stage: ProgressStage): void {
        const tracker = this.contentLengthTrackers.get(id);
        if (tracker) {
            tracker.currentStage = stage;
            // When moving to WRITE stage, ensure we've reached 98% by setting downloaded bytes to total
            if (stage === ProgressStage.WRITE_OPERATION) {
                tracker.currentDownloadedBytes = tracker.totalContentLengthBytes;
            }
            
            this.reportContentLengthProgress(id);
        }
    }

    /**
     * Completes a content-length-based download and cleans up the tracker.
     * @param id - Unique identifier for the download
     */
    public completeContentLengthProgress(id: string): void {
        const tracker = this.contentLengthTrackers.get(id);
        if (tracker) {
            tracker.currentStage = ProgressStage.DOWNLOAD_OPERATION;
            tracker.currentDownloadedBytes = tracker.totalContentLengthBytes;
            this.reportContentLengthProgress(id);
            
            // Clean up immediately - progress reporting is synchronous
            this.contentLengthTrackers.delete(id);
        }
    }

    /**
     * Handles progress events for content-length-based downloads.
     * @param id - Unique identifier for the download
     * @param fetchedBytes - Number of bytes fetched
     * @param totalBytes - Total bytes (optional)
     * @param stage - Current stage of the download process
     */
    public handleProgressEvent(
        id: string, 
        fetchedBytes: number, 
        totalBytes: number | undefined, 
        stage: ProgressStage
    ): void {
        if (fetchedBytes > 0) {
            this.updateContentLengthProgress(id, fetchedBytes, stage);
        }
    }

    /**
     * Converts content length from various units to bytes.
     */
    private convertToBytes(value: number, unit: ContentLengthUnit): number {
        switch (unit) {
            case ContentLengthUnit.KB:
                return value * 1024;
            case ContentLengthUnit.MB:
                return value * 1024 * 1024;
            case ContentLengthUnit.GB:
                return value * 1024 * 1024 * 1024;
            default:
                return value; // Assume bytes if unit is unknown
        }
    }

    /**
     * Calculates progress percentage based on current tracker state.
     */
    private calculateContentLengthProgressPercentage(tracker: ContentLengthProgressTracker): number {
        const { currentDownloadedBytes, totalContentLengthBytes, currentStage } = tracker;
        
        switch (currentStage) {
            case ProgressStage.FETCH_OPERATION:
                // 0-98% based on actual bytes downloaded
                // If we've downloaded all bytes, return exactly 98%
                if (currentDownloadedBytes >= totalContentLengthBytes) return 98;
                return (currentDownloadedBytes / totalContentLengthBytes) * 98;
            case ProgressStage.WRITE_OPERATION:
                // 98-99% for write operation
                return 98 + 0.5; // Fixed progress for write stage
            case ProgressStage.DOWNLOAD_OPERATION:
                // 99-100% for download completion
                return 100;
            default:
                return 0;
        }
    }

    /**
     * Reports progress for a specific content-length-based download.
     */
    private reportContentLengthProgress(id: string): void {
        const tracker = this.contentLengthTrackers.get(id);
        if (tracker && this.onProgressEvent) {
            const progressPercentage = this.calculateContentLengthProgressPercentage(tracker);
            const roundedPercentage = Math.round(progressPercentage * 100) / 100;
            
            // Debug logging
            console.log(`ProgressManager: Reporting content-length progress for ${id}`, {
                progressPercentage: roundedPercentage,
                currentDownloadedBytes: tracker.currentDownloadedBytes,
                totalContentLengthBytes: tracker.totalContentLengthBytes,
                stage: tracker.currentStage
            });
            
            this.onProgressEvent(id, roundedPercentage);
        } else {
            console.warn(`ProgressManager: Cannot report content-length progress for ${id}`, {
                trackerExists: !!tracker,
                onProgressEventExists: !!this.onProgressEvent
            });
        }
    }
  }
const progressManager = new ProgressManager();
export { progressManager };
  