/**
 * CancelHandler manages AbortControllers for video download operations.
 */
class CancelHandler {
    private abortControllers: Map<string, AbortController> = new Map();

    /**
     * Gets or creates an AbortSignal for a given videoId.
     * If an AbortController already exists, returns its signal (throws if aborted).
     * If not, creates a new AbortController, stores it, and returns its signal.
     * @param videoId - The video ID to get or create an AbortSignal for.
     * @returns The AbortSignal for the given videoId.
     * @throws Error('AbortError') if the signal is already aborted.
     */
    public getOrCreateAbortSignal(videoId: string): AbortSignal {
        let ctrl = this.abortControllers.get(videoId);
        if (!ctrl) {
            ctrl = new AbortController();
            this.abortControllers.set(videoId, ctrl);
        }
        if (ctrl.signal.aborted) {
            const error =  new Error('AbortError');
            error.name = 'AbortError';
            throw error;
        }
        return ctrl.signal;
    }

    /**
     * Aborts the AbortController for a given videoId, creating one if it doesn't exist.
     * @param videoId - The video ID to abort.
     */
    public abort(videoId: string): void {
        let ctrl = this.abortControllers.get(videoId);
        if (!ctrl) {
            ctrl = new AbortController();
            this.abortControllers.set(videoId, ctrl);
        }
        ctrl.abort();
    }

    /**
     * Removes the AbortController for a given videoId from the map.
     * @param videoId - The video ID to clean up.
     */
    public cleanup(videoId: string): void {
        this.abortControllers.delete(videoId);
    }
}
export const cancelHandler = new CancelHandler();
