import { DOWNLOAD_STATE, videoAttributes } from "../interfaces";
import helperUtils from "../utils/HelperUtils";

class DownloadService {
    /**
     * Initiates the download of a file by creating a Blob URL and triggering a download action.
     * @param videoId - videoId of the video
     * @param data - The file data as a Blob.
     * @param filename - The name of the file to be downloaded.
     * @returns A promise that resolves when the download is initiated successfully.
     */
    public async downloadFile(videoId: string, attributes: videoAttributes, data: Blob, filename: string): Promise<void> {
        if (!data || !(data instanceof Blob)) {
            helperUtils.sendStateMessage(videoId, attributes, DOWNLOAD_STATE.SERVICE_ERROR);
            console.log('Invalid data provided. Expected a Blob.');
            return;
        }

        try {
            const blobUrl = URL.createObjectURL(data);

            const anchor: HTMLAnchorElement = document.createElement('a');
            anchor.href = blobUrl;
            anchor.download = filename;
            anchor.style.display = 'none';
            document.body.appendChild(anchor);
            anchor.click();
            document.body.removeChild(anchor);
            URL.revokeObjectURL(blobUrl);
        } catch (error) {
            helperUtils.sendStateMessage(videoId, attributes, DOWNLOAD_STATE.SERVICE_ERROR);
            console.error('Error during file download:', error);
            throw error;
        }
    }


}

const downloadService = new DownloadService();
export default downloadService;