import { MEDIA_CONTAINER_FORMAT, MEDIA_TYPE, MediaProcessor, VideoInfo, VideoMediaInfo, OnProgressCallback } from '../interfaces';
import { FFmpeg } from "@ffmpeg/ffmpeg";
import helperUtils from '../utils/HelperUtils';
import { ERROR_NAMES } from '../constants';

const BASE_PATH = 'lib';
const MEDIAPROCESSOR_CORE_JS = 'ffmpeg-core.js';
const MEDIAPROCESSOR_CORE_WASM = 'ffmpeg-core.wasm';

class FetchMediaError extends Error {
    constructor(url: string, originalError: Error) {
        super(`Failed to fetch from ${url}: ${originalError.message}`);
        this.name = ERROR_NAMES.FETCH_MEDIA_ERROR;
        
        // Set the prototype explicitly for TS inheritance support
        Object.setPrototypeOf(this, FetchMediaError.prototype);
    }
}
class MediaProcessorImpl implements MediaProcessor {
    private ffmpeg: FFmpeg;

    constructor() {
        this.ffmpeg = new FFmpeg();
    }


    /**
     * Initializes the FFmpeg library by loading its core and WASM files.
     * @returns A promise that resolves when FFmpeg is successfully initialized.
     */
    async loadMediaProcessor(): Promise<boolean> {
        // TODO: Remove logging for production
        this.ffmpeg.on('log', ({ message }) => {
            console.log(message);
        });
        try {
            await this.ffmpeg.load({
                coreURL: chrome.runtime.getURL(`${BASE_PATH}/${MEDIAPROCESSOR_CORE_JS}`),
                wasmURL: chrome.runtime.getURL(`${BASE_PATH}/${MEDIAPROCESSOR_CORE_WASM}`),
            });
            console.log('FFmpeg loaded successfully');
            return true; // Return true if successful
        } catch (err) {
            console.error('Error loading FFmpeg:', err);
            return false; // Return false if an error occurs
        }
    }

    /**
     * Fetches a file from the given URL with optional progress tracking.
     * @param url - The URL of the file to fetch.
     * @param abortSignal - Signal to abort the fetch operation.
     * @param onProgress - Optional callback to track download progress (fetched bytes, total bytes).
     * @returns A promise that resolves to the fetched file data.
     */
    async fetchFileData(url: string, abortSignal: AbortSignal, onProgress?: OnProgressCallback): Promise<Uint8Array> {
        try {
            const response = await fetch(url, { signal: abortSignal });
            if (!response.ok) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }

            const contentLength = response.headers.get('Content-Length');
            if (!contentLength) {
                const error = new Error('Content-Length header is missing - cannot determine file size');
                error.name = ERROR_NAMES.FETCH_MEDIA_ERROR;
                throw error;
            }
            
            const totalBytes = parseInt(contentLength, 10);
            if (isNaN(totalBytes) || totalBytes <= 0) {
                const error = new Error(`Invalid Content-Length header: ${contentLength}`);
                error.name = ERROR_NAMES.FETCH_MEDIA_ERROR;
                throw error;
            }
            
            if (!response.body) {
                throw new Error('Response body is null');
            }

            const reader = response.body.getReader();
            const streamBuffers: Uint8Array[] = [];
            let fetchedBytes = 0;

            try {
                while (true) {
                    const { done, value } = await reader.read();
                    
                    if (done) break;
                    
                    streamBuffers.push(value);
                    fetchedBytes += value.length;
                    
                    // Safe progress reporting
                    if (onProgress) {
                        try {
                            onProgress(fetchedBytes, totalBytes);
                        } catch (progressError) {
                            console.warn('Progress callback error:', progressError);
                            // Continue download even if progress reporting fails
                        }
                    }
                }
            } catch (error) {
                console.error('Download error:', error);
                
                // Clean up resources
                if (reader) {
                    try {
                        reader.releaseLock();
                    } catch (releaseError) {
                        console.warn('Reader cleanup error:', releaseError);
                    }
                }
                
                // Re-throw with proper error handling
                if (error.name === 'AbortError') {
                    throw error;
                } else {
                    const fetchError = new Error(`Download failed: ${error.message}`);
                    fetchError.name = ERROR_NAMES.FETCH_MEDIA_ERROR;
                    throw fetchError;
                }
            } finally {
                // Ensure cleanup
                if (reader) {
                    try {
                        reader.releaseLock();
                    } catch (releaseError) {
                        console.warn('Final cleanup error:', releaseError);
                    }
                }
            }

            const totalLength = streamBuffers.reduce((sum, buffer) => sum + buffer.length, 0);
            const result = new Uint8Array(totalLength);
            let offset = 0;
            
            for (const buffer of streamBuffers) {
                result.set(buffer, offset);
                offset += buffer.length;
            }

            return result;
        } catch (error) {
            console.error(`Error fetching file from URL: ${url}`, error);
            if (error.name === 'AbortError') {
                throw error; // Re-throw AbortError as-is for cancellation handling
            }
            // Convert any error to FetchMediaError with consistent message format
            const fetchError = new FetchMediaError(url, error);
            throw fetchError;
        }
    }


    /**
     * Writes the audio and video data to to the FFmpeg virtual file system.
     * @param data - The audio or video data to write.
     * @param fileName - The path where the data will be written in the wasmfile
     * @returns A promise that resolves when the files are successfully written.
     */
    async writeFile(data: Uint8Array, fileName: string, abortSignal: AbortSignal): Promise<void> {
        try {
            await this.ffmpeg.writeFile(fileName, data, { signal: abortSignal });
        } catch (error) {
            console.error(`Error writing file ${fileName}:`, error);
            throw error;
        }
        try {
            await this.ffmpeg.readFile(fileName, undefined, { signal: abortSignal });
        } catch (error) {
            console.error(`Error reading file ${fileName}:`, error);
            throw error;
        }
    }

    /**
     * Deletes a file from the FFmpeg wasm memory
     * @param fileName - The name of the file to delete from the wasm.
     * @returns A promise that resolves when the file is successfully deleted.
     */
    async deleteFile(fileName: string): Promise<void> {
        try {
            await this.ffmpeg.deleteFile(fileName);
        } catch (error) {
            throw error;
        }
    }

    /**
     * Merges the audio and video files into a single file.
     * @param internalAudioFileName - The audio data file name to merge.
     * @param internalVideoFileName - The video data file name to merge.
     * @param outputFileName - Final file name .
     * @returns A promise that resolves to the merged file.
     */    
    async mergeFiles(internalAudioFileName: string, internalVideoFileName: string, outputFileName: string, mediaContainerFormat: MEDIA_CONTAINER_FORMAT, abortSignal: AbortSignal): Promise<Blob> {
        try {
            await this.ffmpeg.exec([
                '-i', internalVideoFileName, '-i', internalAudioFileName, '-c', 'copy', outputFileName
            ], undefined, { signal: abortSignal });
        } catch (error: any) {
            console.error(`Error merging files ${internalAudioFileName} and ${internalVideoFileName} into ${outputFileName}:`, error);
            if (error.name === 'AbortError') {
                throw error; // Re-throw AbortError as-is for cancellation handling
            }
            const mergeError = new Error(`Error merging files ${internalAudioFileName} and ${internalVideoFileName} into ${outputFileName}: ${error.message}`);
            mergeError.name = ERROR_NAMES.FILE_MERGE_ERROR;
            throw mergeError;
        }
        let finalData;
        try {
            finalData = await this.ffmpeg.readFile(outputFileName, undefined, { signal: abortSignal });
        } catch (error: any) {
            if (error.name === 'AbortError') {
                throw error; // Re-throw AbortError as-is for cancellation handling
            }
            const readError = new Error(`Error reading merged file ${outputFileName}: ${error.message}`);
            readError.name = ERROR_NAMES.FILE_MERGE_ERROR;
            throw readError;
        }
        if (!finalData || finalData.length === 0) {
            const emptyFileError = new Error(`Merged file ${outputFileName} is empty or invalid.`);
            emptyFileError.name = ERROR_NAMES.FILE_MERGE_ERROR;
            throw emptyFileError;
        }
        const finalBlob: Blob = new Blob([finalData], {type: `video/${mediaContainerFormat.toLowerCase()}`});
        return finalBlob;
    }

    /**
     * Merges multiple video or audio segments into a single Uint8Array.
     * @param segments - An array of URLs pointing to the segments.
     * @param mediaType - The type of media (e.g., video or audio).
     * @param mediaContainer - The container format (e.g., WEBM, MP4).
     * @param initSegmentBase64 - Base64-encoded initialization segment (optional).
     * @param indexSegmentUrl - URL of the index segment (optional).
     * @param abortSignal - Signal to abort the operation.
     * @param onProgress - Optional callback to track download progress (loaded bytes, total bytes).
     * @returns A promise that resolves to the merged segments as a Uint8Array.
     */
    public async mergeSegments(
        segments: string[],
        mediaType: MEDIA_TYPE,
        mediaContainer: MEDIA_CONTAINER_FORMAT,
        initSegmentBase64: string = undefined,
        indexSegmentUrl: string = undefined,
        abortSignal: AbortSignal,
        onProgress?: OnProgressCallback
    ): Promise<Uint8Array> {
        if (!segments || segments.length === 0) {
            throw new Error('No segments provided. Please provide valid segment URLs.');
        }
        const mimeType = `${mediaType === MEDIA_TYPE.VIDEO ? MEDIA_TYPE.VIDEO : MEDIA_TYPE.AUDIO}/${mediaContainer.toLowerCase()}`;
        
        // Concatenate all segments into a Blob array
        const blobArr = await this.concatSegments(segments, initSegmentBase64, indexSegmentUrl, mimeType, abortSignal, onProgress);
        if (blobArr.length === 0) {
            throw new Error('No segments to merge. Please provide valid segment URLs.');
        }

        // Create a Blob from the concatenated segments
        const mergedBlob = new Blob(blobArr, { type: mimeType });

        // Convert the Blob to Uint8Array
        return await this.blobToUint8Array(mergedBlob);
    }

    /**
     * Concatenates video or audio segments into a Blob array.
     * @param segmentUrls - An array of segment URLs to fetch and concatenate.
     * @param initSegmentBase64 - Base64-encoded initialization segment (optional).
     * @param indexSegmentUrl - URL of the index segment (optional).
     * @param mimeType - MIME type of the media.
     * @param abortSignal - Signal to abort the operation.
     * @param onProgress - Optional callback to track download progress (loaded bytes, total bytes).
     * @returns A promise that resolves to an array of Blobs representing the concatenated segments.
     */
    private async concatSegments(segmentUrls: string[], initSegmentBase64: string, indexSegmentUrl: string, mimeType: string, abortSignal: AbortSignal, onProgress?: (fetchedBytes: number, totalBytes?: number) => void): Promise<Blob[]> {
        const blobArr: Blob[] = [];

        // Add the init segment as a Blob
        if (initSegmentBase64) {
            blobArr.push(helperUtils.base64ToBlob(initSegmentBase64, mimeType));
        }

        // Add the index segment as a Blob
        if (indexSegmentUrl) {
            try {
                const response = await fetch(indexSegmentUrl, { signal: abortSignal });
                if (!response.ok) {
                    console.error(`Failed to fetch index segment from ${indexSegmentUrl}. Status: ${response.status}`);
                    throw new Error(`Failed to fetch index segment. Status: ${response.status}`);
                }
                const indexSegmentBlob = await response.blob();
                if (!indexSegmentBlob) {
                    console.error(`Index segment fetch returned null or undefined for URL: ${indexSegmentUrl}`);
                    throw new Error('Index segment fetch returned null or undefined.');
                }
                blobArr.push(indexSegmentBlob);
                
                // Report progress for index segment
                if (onProgress) {
                    onProgress(indexSegmentBlob.size, 0);
                }
            } catch (error) {
                console.error(`Error fetching index segment from ${indexSegmentUrl}:`, error);
                if (error.name === 'AbortError') {
                    throw error; // Re-throw AbortError as-is for cancellation handling
                }
                const fetchError = new FetchMediaError(indexSegmentUrl, error);
                throw fetchError;
            }
        }

        // Add all segments to the blob array and fetch all segments in parallel
        const segmentBlobs = await Promise.all(
            segmentUrls.map(async (segmentUrl) => {
                try {
                    const response = await fetch(segmentUrl, { signal: abortSignal });
                    if (!response.ok) {
                        console.error(`Failed to fetch segment from ${segmentUrl}. Status: ${response.status}`);
                        throw new Error(`Failed to fetch segment. Status: ${response.status}`);
                    }
                    const segmentBlob = await response.blob();
                    if (!segmentBlob) {
                        console.error(`Segment fetch returned null or undefined response for URL: ${segmentUrl}`);
                        throw new Error('Segment fetch returned null or undefined.');
                    }
                    
                    // Report progress for this segment
                    if (onProgress) {
                        onProgress(segmentBlob.size, 0);
                    }
                    
                    return segmentBlob;
                } catch (error) {
                    console.error(`Error fetching segment from ${segmentUrl}:`, error);
                    if (error.name === 'AbortError') {
                        throw error; // Re-throw AbortError as-is for cancellation handling
                    }
                    const fetchError = new FetchMediaError(segmentUrl, error);
                    throw fetchError;
                }
            })
        );
        blobArr.push(...segmentBlobs);
        return blobArr;
    }

    private async blobToUint8Array(blob: Blob): Promise<Uint8Array> {
        const arrayBuffer = await blob.arrayBuffer();
        return new Uint8Array(arrayBuffer);
    }
}
const mediaProcessorImpl = new MediaProcessorImpl();

export default mediaProcessorImpl;
