import { VideoInfo, DOWNLOAD_STATE, VideoDownloadStatus, VideoMediaInfo, MEDIA_TYPE, MEDIA_CONTAINER_FORMAT, VIDEO_FORMAT, AUDIO_FORMAT, ProgressStage, videoAttributes, OnProgressCallback } from '../interfaces';
import downloadService from './DownloadService';
import mediaProcessorImpl from './MediaProcessorImpl';
import helperUtils  from '../utils/HelperUtils';
import { progressManager } from './ProgressManager';
import { OFFSCREEN_MESSAGE_TYPES, ERROR_NAMES } from '../constants';
import { cancelHandler } from './CancelHandler';
class VideoDownloadManager {
    
    private isInitialized: boolean = false;
    private initPromise: Promise<boolean> | null = null;

    constructor() {}

    /**
     * Creates a progress callback function for a specific video download.
     *
     * @param key - The unique identifier for the video download.
     * @param stage - The current progress stage.
     * @returns A progress callback function.
     */
    private createProgressCallback(key: string, stage: ProgressStage): OnProgressCallback {
        return (fetchedBytes: number, totalBytes?: number) => {
            progressManager.handleProgressEvent(key, fetchedBytes, totalBytes, stage);
        };
    }

    /**
     * Handles the progress event for a video download.
     *
     * @param progressPercentage - The current progress percentage of the video download.
     * @param videoId - The unique identifier of the video being downloaded.
     */
    onProgressEvent(videoId: string, progressPercentage: number) {
        chrome.runtime.sendMessage({
            type: OFFSCREEN_MESSAGE_TYPES.PROGRESS_UPDATED,
            progressInformation: {
                videoId,
                progressPercentage,
            }
        });
    }

    private async fetchAndMergeAudioSegments(videoMediaInfo: VideoMediaInfo): Promise<Blob | null> {
        let audioData: Uint8Array = null;
        const key: string = helperUtils.getKey(videoMediaInfo.videoId, videoMediaInfo.videoAttributes);
        if (videoMediaInfo.audioSpecificInfo.audioSegmentURLs.length === 0) {
            console.error(`No audio segments found for video ${videoMediaInfo.videoId}.`);
            progressManager.stop(key);
            helperUtils.sendStateMessage(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, DOWNLOAD_STATE.MEDIA_ERROR);
            return null;
        }
        if (videoMediaInfo.audioSpecificInfo.audioSegmentURLs.length > 1 ) {
            // Multi-segment audio
            const abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
            audioData = await mediaProcessorImpl.mergeSegments(
                videoMediaInfo.audioSpecificInfo.audioSegmentURLs,
                MEDIA_TYPE.AUDIO,
                videoMediaInfo.mediaContainerFormat,
                videoMediaInfo.audioSpecificInfo.initSegmentBase64,
                videoMediaInfo.audioSpecificInfo.indexSegmentUrl,
                abortSignal,
                this.createProgressCallback(key, ProgressStage.FETCH_OPERATION)
            );
        } else {
            // Single-segment audio
            const abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
            audioData = await mediaProcessorImpl.fetchFileData(
                videoMediaInfo.audioSpecificInfo.audioSegmentURLs[0], 
                abortSignal,
                this.createProgressCallback(key, ProgressStage.FETCH_OPERATION)
            );
        }        
        return new Blob([audioData as BlobPart], { type: `audio/${videoMediaInfo.mediaContainerFormat.toLowerCase()}` });
    }

    /**
     * Downloads multiple videos concurrently for fetching data and processingthem when they are fetched.
     * @param videoInfos - An array of VideoInfo objects containing video and audio URLs.
     */
    public async downloadVideos(videoMediaInfos: VideoMediaInfo[]): Promise<void> {
        try {
            const fetchAndProcessPromises = videoMediaInfos.map(async (videoMediaInfo) => {
                const ffmpegWasmFileList: string[] = [];
                const startTime = Date.now(); // Start time for download
                try {
                    const key: string = helperUtils.getKey(videoMediaInfo.videoId, videoMediaInfo.videoAttributes);
                    let finalBlob: Blob = null;
                    
                    console.log(`VideoDownloadManager: Starting download for ${key}`, {
                        videoId: videoMediaInfo.videoId,
                        isAudioOnly: videoMediaInfo.isAudioOnly,
                        hasVideoSpecificInfo: !!videoMediaInfo.videoSpecificInfo,
                        videoSegmentURLsLength: videoMediaInfo.videoSpecificInfo?.videoSegmentURLs?.length || 0
                    });
                    
                    // Initialize content-length-based progress tracking
                    progressManager.startDownloadProgressStatus(videoMediaInfo, key, this.onProgressEvent);
                    
                    // Fetch audio and video data concurrently

                    if (videoMediaInfo.isAudioOnly || !videoMediaInfo.videoSpecificInfo.videoSegmentURLs.length) {
                        // Handle audio-only case or missing videoSegmentURLs
                        console.log(`VideoDownloadManager: Taking audio-only path for ${key}`);
                        finalBlob = await this.fetchAndMergeAudioSegments(videoMediaInfo);
                        
                        // Move to WRITE stage and then DOWNLOAD stage for audio-only
                        progressManager.setContentLengthStage(key, ProgressStage.WRITE_OPERATION);
                        progressManager.setContentLengthStage(key, ProgressStage.DOWNLOAD_OPERATION);
                        progressManager.completeContentLengthProgress(key);

                    } else if (videoMediaInfo.videoSpecificInfo.videoSegmentURLs.length > 1 ) {
                        console.log(`VideoDownloadManager: Taking multi-segment path for ${key}`);
                        // Multi-segment video
                        let abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        const videoData = await mediaProcessorImpl.mergeSegments(
                            videoMediaInfo.videoSpecificInfo.videoSegmentURLs,
                            MEDIA_TYPE.VIDEO,
                            videoMediaInfo.mediaContainerFormat,
                            videoMediaInfo.videoSpecificInfo.initSegmentBase64,
                            videoMediaInfo.videoSpecificInfo.indexSegmentUrl,
                            abortSignal,
                            (loaded, total) => {
                                // Report progress based on actual bytes downloaded
                                if (loaded > 0) {
                                    progressManager.updateContentLengthProgress(key, loaded, ProgressStage.FETCH_OPERATION);
                                }
                            }
                        );
                        abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        const audioData = await mediaProcessorImpl.mergeSegments(
                            videoMediaInfo.audioSpecificInfo.audioSegmentURLs,
                            MEDIA_TYPE.AUDIO,
                            videoMediaInfo.mediaContainerFormat,
                            videoMediaInfo.audioSpecificInfo.initSegmentBase64,
                            videoMediaInfo.audioSpecificInfo.indexSegmentUrl,
                            abortSignal,
                            (loaded, total) => {
                                // Report progress based on actual bytes downloaded
                                if (loaded > 0) {
                                    progressManager.updateContentLengthProgress(key, loaded, ProgressStage.FETCH_OPERATION);
                                }
                            }
                        );
                        
                        // Move to WRITE stage
                        progressManager.setContentLengthStage(key, ProgressStage.WRITE_OPERATION);
                        const videoFileName = `video-${videoMediaInfo.videoId}.${videoMediaInfo.mediaContainerFormat}`;
                        const audioFileName = `audio-${videoMediaInfo.videoId}.${videoMediaInfo.mediaContainerFormat}`;
                        const outputFileName = `output-${videoMediaInfo.videoId}.${videoMediaInfo.mediaContainerFormat}`;
                        ffmpegWasmFileList.push(audioFileName, videoFileName, outputFileName);
                        abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        await mediaProcessorImpl.writeFile(audioData, audioFileName, abortSignal);
                        abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        await mediaProcessorImpl.writeFile(videoData, videoFileName, abortSignal);
                        abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        finalBlob = await mediaProcessorImpl.mergeFiles(audioFileName, videoFileName, outputFileName, videoMediaInfo.mediaContainerFormat, abortSignal);
                        
                        // Move to DOWNLOAD stage and complete
                        progressManager.setContentLengthStage(key, ProgressStage.DOWNLOAD_OPERATION);
                        progressManager.completeContentLengthProgress(key);
                    } else if (videoMediaInfo.videoSpecificInfo.videoSegmentURLs.length === 1) {
                        console.log(`VideoDownloadManager: Taking single-segment path for ${key}`);
                        let abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        // Single-segment video
                        
                        const [audioData, videoData] = await Promise.all([
                            mediaProcessorImpl.fetchFileData(
                                videoMediaInfo.audioSpecificInfo.audioSegmentURLs[0], 
                                abortSignal,
                                this.createProgressCallback(key, ProgressStage.FETCH_OPERATION)
                            ),
                            mediaProcessorImpl.fetchFileData(
                                videoMediaInfo.videoSpecificInfo.videoSegmentURLs[0], 
                                abortSignal,
                                this.createProgressCallback(key, ProgressStage.FETCH_OPERATION)
                            )
                        ]);

                        // Move to WRITE stage
                        progressManager.setContentLengthStage(key, ProgressStage.WRITE_OPERATION);

                        const videoFileName = `video-${videoMediaInfo.videoId}.${videoMediaInfo.guid}.${videoMediaInfo.mediaContainerFormat}`;
                        const audioFileName = `audio-${videoMediaInfo.videoId}.${videoMediaInfo.guid}.${videoMediaInfo.mediaContainerFormat}`;
                        const outputFileName = `output-${videoMediaInfo.videoId}.${videoMediaInfo.mediaContainerFormat}`;
                        ffmpegWasmFileList.push(audioFileName, videoFileName, outputFileName);

                        abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        await mediaProcessorImpl.writeFile(audioData, audioFileName, abortSignal);
                        abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        await mediaProcessorImpl.writeFile(videoData, videoFileName, abortSignal);
                        abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                        finalBlob = await mediaProcessorImpl.mergeFiles(audioFileName, videoFileName, outputFileName, videoMediaInfo.mediaContainerFormat, abortSignal);
                        
                        // Move to DOWNLOAD stage and complete
                        progressManager.setContentLengthStage(key, ProgressStage.DOWNLOAD_OPERATION);
                        progressManager.completeContentLengthProgress(key);
                    }

                    if (!finalBlob || !(finalBlob instanceof Blob)) {
                        console.error(`Invalid finalBlob for video ${videoMediaInfo.videoId}.`);
                        helperUtils.sendStateMessage(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, DOWNLOAD_STATE.MEDIA_ERROR);
                        return;
                    }
                    let abortSignal = cancelHandler.getOrCreateAbortSignal(videoMediaInfo.videoId);
                    await downloadService.downloadFile(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, finalBlob, `${videoMediaInfo.videoId}-${videoMediaInfo.title}.${videoMediaInfo.mediaContainerFormat}`);
                    // Move to DOWNLOAD stage and complete
                    progressManager.setContentLengthStage(key, ProgressStage.DOWNLOAD_OPERATION);
                    progressManager.completeContentLengthProgress(key);

                    const endTime = Date.now(); // End time for successful download
                    const downloadTime = (endTime - startTime) / 1000; // Calculate time in seconds
                    console.log(`Download completed for video ${videoMediaInfo.videoId} in ${downloadTime} seconds.`);
                    helperUtils.sendStateMessage(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, DOWNLOAD_STATE.COMPLETED);
                    cancelHandler.cleanup(videoMediaInfo.videoId);
                } catch (error) {
                    const key: string = helperUtils.getKey(videoMediaInfo.videoId, videoMediaInfo.videoAttributes);
                    cancelHandler.cleanup(videoMediaInfo.videoId);
                    const failureTime = (Date.now() - startTime) / 1000; // Calculate time until failure
                    if (error.name === 'AbortError') {
                        console.warn(`Cancelled ${videoMediaInfo.videoId} after ${failureTime} seconds:`, error);
                        helperUtils.sendStateMessage(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, DOWNLOAD_STATE.CANCELLED);
                    } else if (error.name === ERROR_NAMES.FETCH_MEDIA_ERROR) {
                        progressManager.stop(key);
                        console.error(`Network error processing video ${videoMediaInfo.videoId} after ${failureTime} seconds:`, error);
                        helperUtils.sendStateMessage(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, DOWNLOAD_STATE.NETWORK_ERROR);
                    } else if (error.name === ERROR_NAMES.FILE_MERGE_ERROR) {
                        progressManager.stop(key);
                        console.error(`File merge error processing video ${videoMediaInfo.videoId} after ${failureTime} seconds:`, error);
                        helperUtils.sendStateMessage(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, DOWNLOAD_STATE.FILE_MERGE_ERROR);
                    }
                    else {
                        progressManager.stop(key);
                        console.error(`Error processing video ${videoMediaInfo.videoId} after ${failureTime} seconds:`, error);
                        helperUtils.sendStateMessage(videoMediaInfo.videoId, videoMediaInfo.videoAttributes, DOWNLOAD_STATE.MEDIA_ERROR);
                    }

                } finally {
                    // Do mediaProcessor file cleanup
                    await this.deleteMediaProcessorFiles(ffmpegWasmFileList);
                }
            });

            // Wait for all fetch and process operations to complete
            await Promise.all(fetchAndProcessPromises);
        } catch (error) {
            // Send a message with the error state for media processing
            const errorPayload = {
                videoIds: videoMediaInfos.map(videoMediaInfo => videoMediaInfo.videoId),
                state: DOWNLOAD_STATE.MEDIA_ERROR
            };
            chrome.runtime.sendMessage(errorPayload);

            console.error('Error during batch download:', error);
        }
    }

    /**
     * Loads the media processor with a timeout.
     */
    public async init(timeout: number): Promise<boolean> {
        if (this.isInitialized) {
            return true; // Already initialized
        }

        if (this.initPromise) {
            return this.initPromise; // Return the ongoing initialization promise
        }

        const timeoutPromise = new Promise<boolean>((_, reject) => {
            setTimeout(() => reject(new Error('Initialization timeout exceeded.')), timeout);
        });

        this.initPromise = Promise.race([
            mediaProcessorImpl.loadMediaProcessor(),
            timeoutPromise
        ])
            .then((isLoaded) => {
                this.isInitialized = Boolean(isLoaded); // Ensure isInitialized is explicitly set to true if successful
                return this.isInitialized;
            })
            .catch((error) => {
                console.error('Failed to initialize Media Processor:', error);
                throw error;
            })
            .finally(() => {
                this.initPromise = null;
            });

        return this.initPromise;
    }

    /**
     * Cancels processing and download for a given videoId.
     * @param videoId - The video ID to cancel.
     */
    public cancelVideo(videoId: string, videoAttributes: videoAttributes): void {
        cancelHandler.abort(videoId);
        progressManager.stop(helperUtils.getKey(videoId, videoAttributes));
    }

    /**
     * Deletes files from the media processor file system.
     * @param fileNames - Array of file names to delete from the media processor file system.
     */
    private async deleteMediaProcessorFiles(fileNames: string[]): Promise<void> {
        for (const fileName of fileNames) {
            try {
                await mediaProcessorImpl.deleteFile(fileName);
            } catch (error) {
                console.error(`Failed to delete file ${fileName}:`, error);
            }
        }
    }

}

const videoDownloadManager = new VideoDownloadManager();
export default videoDownloadManager;
