import { MESSAGE_TYPES, CONSTANTS, OFFSCREEN_MESSAGE_TYPES } from '../constants';
import { MEDIA_CONTAINER_FORMAT, VideoInfo, VideoMediaInfo } from '../interfaces';
import videoDownloadManager from './VideoDownloadManager';
import poTokenManager from './PoTokenManager';

const SANDBOX_IFRAME_ID = '__sandbox_iframe__';
const MEDIAPROCESSOR_LOAD_MAX_TIMEOUT = 120000;

/**
 * Offscreen document that handles:
 * 1. Video download processing with FFmpeg
 * 2. PoToken generation via sandbox iframe
 * 3. Script execution in sandboxed iframe
 */
class OffscreenVideoDownloader {
    private iframe: HTMLIFrameElement | null = null;
    private videoDownloadManagerInitialised: boolean = false;

    constructor() {
        this.handleMessages = this.handleMessages.bind(this);
        this.initListeners = this.initListeners.bind(this);
    }
    
    /**
     * Handles incoming messages from other parts of the extension.
     * 
     * @param message - The message object containing the type and data of the request.
     * @param sender - The sender of the message, provided by the Chrome runtime.
     * @param sendResponse - A callback function to send a response back to the sender.
     * @returns A promise that resolves when the message is processed.
     */
    handleMessages(message: any, sender: chrome.runtime.MessageSender, sendResponse: (response: any) => void): any {
        try {
            console.log('Received message:', message);
            console.log('Sender:', sender);

            if (message.type === MESSAGE_TYPES.DOWNLOAD_MEDIA) {
                this.triggerDownloadMedia(message.videoInfo).then(() => {
                    sendResponse({ payload: { success: true, message: 'Download started' } });
                }
                ).catch((error) => {
                    console.error('Error downloading media: ', error);
                }
                );
            } 
            else if (message.type === MESSAGE_TYPES.CANCEL_DOWNLOAD) {
                // Per-video cancellation
                if (message.videoMediaId) {
                    videoDownloadManager.cancelVideo(message.videoMediaId, message.videoAttributes);
                    console.log("message offscreen",message);
                } else {
                    sendResponse({ payload: { success: false, error: 'Missing videoMediaId for cancellation' } });
                }
            }
            else if(message.type === MESSAGE_TYPES.EXECUTE_SCRIPT) {
                if (typeof message?.payload?.context !== 'object') {
                    console.error('Invalid payload context:', message.payload);
                    sendResponse({
                        payload: {
                            success: false,
                            error: 'Invalid payload context'
                        }
                    });
                    return;
                }

                // Constructs JavaScript code by mapping the context object / nCode into variable declarations.
                // Executes the combined code (context + script) in a sandboxed environment.
                // Sends the result or error back to the sender
                const jsCode = Object.entries(message.payload.context)
                    .map(([key, value]) => {
                        const val = typeof value === "string" ? `'${value}'` : value;
                        return `let ${key} = ${val};`;
                    })
                    .join('\n');
                
                // Wrap in IIFE to allow return statements in the evaluated code
                const wrappedCode = `(function() { ${jsCode} ${message.payload.code}; return exportedVars; })()`;
                this.evaluateInSandbox(wrappedCode).then((result) => {
                    sendResponse({
                        payload: {
                            result
                        }
                    });
                }).catch((error) => {
                    console.error('Error executing script:', error);
                    sendResponse({
                        payload: {
                            error: error.message
                        }
                    });
                });
            }
            else if(message.type === MESSAGE_TYPES.GENERATE_PO_TOKENS) {
                // Generate PoTokens
                const tokens = poTokenManager.generateTokens();
                if (tokens) {
                    console.debug('PoTokens generated successfully:', {
                        hasVisitorData: !!tokens.visitorData,
                        hasPoToken: !!tokens.poToken
                    });
                    sendResponse({
                        payload: {
                            success: true,
                            tokens
                        }
                    });
                } else {
                    console.error('Failed to generate PoTokens');
                    sendResponse({
                        payload: {
                            success: false,
                            error: 'Failed to generate PoTokens'
                        }
                    });
                }
            }
        } catch (error) {
            console.error('Error in handleMessages:', error);
            sendResponse({ payload: { success: false, error: error.message } });
        }
        return true;
    }

    /**
     * Evaluates JavaScript code in a sandboxed iframe.
     * 
     * @param content - The JavaScript code to evaluate.
     * @returns A promise that resolves to the result of the evaluation.
     */
    evaluateInSandbox(content: string): Promise<any> {
        return new Promise((resolve, reject) => {
            if (!this.iframe) {
                reject(new Error('Iframe is not initialized. Call init() first.'));
                return;
            }

            const messageHandler = (event: MessageEvent) => {
                // Ensure we only process messages from our iframe
                if (event.source === this.iframe?.contentWindow) {
                    window.removeEventListener('message', messageHandler);
                    // Check if error property exists first
                    if (event.data?.error) {
                        reject(new Error(event.data.error));
                    } else if ('result' in event.data) {
                        // Resolve with result even if it's undefined (script executed successfully)
                        resolve(event.data.result);
                    } else {
                        reject(new Error('Unknown error occurred in sandbox iframe.'));
                    }
                }
            };

            const sendMessage = () => {
                window.addEventListener('message', messageHandler); // Adding listener for sandbox iframe messages
                this.iframe.contentWindow.postMessage({ content }, '*');
            };

            if (this.iframe.contentWindow) {
                sendMessage();
            } else {
                // If the iframe's contentWindow is not available , or is still loading, the sendMessage function will be executed once the iframe has finished loading.
                this.iframe.onload = sendMessage;
            }
        });
    }

    /**
     * Initiates the download of media based on the provided video information.
     * 
     * @param videoMediaInfos - An array of type `VideoMediaInfo` containing details about the video to download.
     */
    async triggerDownloadMedia(videoMediaInfos: VideoMediaInfo[]): Promise<void> {
        console.log('Downloading media:', videoMediaInfos);
        if (!this.videoDownloadManagerInitialised) {
            // TODO : Send the status message to the sender saying that the video download manager is not initialized
            return;
        }
        await videoDownloadManager.downloadVideos(videoMediaInfos);
    }

   /**
   * Initializes listeners for handling runtime messages.
   */
  initListeners(): void { 
    // Create iframe only once   
      chrome.runtime.onMessage.addListener(offscreenVideoDownloader.handleMessages);      
  }
 async init (): Promise<void> {
    console.log('OffscreenVideoDownloader initialized');
    await this.initListeners();
    // Ensure iframe is created during initialization
    if (!this.iframe) {
        this.iframe = document.createElement('iframe') as HTMLIFrameElement;
        this.iframe.id = SANDBOX_IFRAME_ID;
        this.iframe.src = chrome.runtime.getURL('views/sandbox.html');
        this.iframe.style.display = 'none';
        document.body.appendChild(this.iframe);
    }
    this.videoDownloadManagerInitialised = await videoDownloadManager.init(MEDIAPROCESSOR_LOAD_MAX_TIMEOUT);
 }
  
}

const offscreenVideoDownloader = new OffscreenVideoDownloader();
offscreenVideoDownloader.init();
export default offscreenVideoDownloader;
