import * as YouTubeLib from '@avast/youtube-downloader-lib';

export interface PoTokenResult {
    visitorData: string;
    poToken: string;
}

export interface PoTokenManagerConfig {
    /** Custom BotGuard request key (falls back to YouTubeLib.DEFAULT_BOTGUARD_REQUEST_KEY) */
    requestKey?: string;
}

/**
 * Manages PoToken generation for YouTube video requests.
 */
class PoTokenManager {
    private requestKey: string;

    constructor(config: PoTokenManagerConfig = {}) {
        this.requestKey = config.requestKey ?? YouTubeLib.DEFAULT_BOTGUARD_REQUEST_KEY;
    }

    /**
     * Generate PoToken and visitor data for YouTube authentication.
     * Currently uses placeholder tokens (requestKey not needed).
     * 
     * @returns PoTokenResult or null if generation fails
     */
    generateTokens(): PoTokenResult | null {
        try {
            const visitorData = YouTubeLib.generateVisitorData();
            const poToken = YouTubeLib.generatePlaceholderToken(visitorData);           
            return {
                visitorData,
                poToken
            };
        } catch (error: any) {
            console.error('PoTokenManager: Failed to generate tokens:', error.message);
            return null;
        }
    }
}

const poTokenManager = new PoTokenManager();
export default poTokenManager;